tool_input.command:
cat > /etc/nginx/sites-available/default << 'EOF'
server {
    listen 8443 ssl;
    server_name localhost;

    ssl_certificate /etc/ssl/certs/cert.pem;
    ssl_certificate_key /etc/ssl/private/key.pem;

    # Main branch
    location / {
        root /var/www/html;
        index index.html;
    }

    # Dev branch
    location /dev/ {
        alias /var/www/html/dev/;
        index index.html;
    }
}
EOF
echo "Nginx config created"
